package models

import (
	"encoding/json"
	"testing"

	"novelstudio/internal/domain"
	"novelstudio/internal/skills"
)

// Literal pre-extraction wire snapshots protect queued requests, quoted request
// hashes and replay fingerprints. They are not generated by the new renderer.
func TestCapabilityMethodKeepsLegacyWireProjection(t *testing.T) {
	schema := json.RawMessage(`{"type":"object","properties":{"source":{"type":"string"}},"required":["source"],"additionalProperties":false}`)
	root := domain.CapabilityVersion{ID: "agent-v1", Definition: domain.CapabilityDefinition{Kind: "agent", InputSchema: schema, OutputSchema: json.RawMessage(`{"type":"string"}`), Instructions: "守住主线。"}}
	method := domain.CapabilityVersion{ID: "skill-v1", Definition: domain.CapabilityDefinition{Kind: "skill", PackageID: "pkg-v1", PackageHash: "bundle-sha", Instructions: "保留细节。"}}
	bundles := map[string]skills.Bundle{"pkg-v1": {Files: []skills.File{{Path: "SKILL.md", Data: []byte("方法原文")}, {Path: "scripts/tool.py", Data: []byte("not copied")}, {Path: "bad.txt", Data: []byte{0xff}}}}}
	input := json.RawMessage(`{"source":"渡口"}`)
	for _, trial := range []bool{true, false} {
		request, err := AppendCapabilityMethod(Request{Prompt: "原始要求", System: "原始规则"}, root, "manifest-sha", []domain.CapabilityVersion{root, method}, bundles, input, trial)
		if err != nil {
			t.Fatal(err)
		}
		want := "原始要求\n<fixed-method-data>\n" + `{"input":{"source":"渡口"},"manifest_hash":"manifest-sha","methods":[{"files":[{"path":"SKILL.md","text":"方法原文"}],"instructions":"保留细节。","package_hash":"bundle-sha","version_id":"skill-v1"}]}` + "\n</fixed-method-data>"
		if trial {
			want = "原始要求\n\n<capability-trial-data>\n" + `{"agent_version":"agent-v1","input":{"source":"渡口"},"manifest_hash":"manifest-sha","methods":[{"files":[{"path":"SKILL.md","text":"方法原文"}],"instructions":"保留细节。","package_hash":"bundle-sha","version_id":"skill-v1"}]}` + "\n</capability-trial-data>"
		}
		if request.Prompt != want || string(request.Schema) != `{"type":"string"}` {
			t.Fatal("queued request wire projection changed", trial, request.Prompt)
		}
	}
	if _, err := AppendCapabilityMethod(Request{}, root, "manifest-sha", []domain.CapabilityVersion{method}, nil, input, true); err == nil {
		t.Fatal("missing method bundle silently omitted")
	}
	if _, err := AppendCapabilityMethod(Request{}, root, "manifest-sha", nil, nil, json.RawMessage(`{"source":3}`), true); err == nil {
		t.Fatal("invalid professional input accepted")
	}
}
